import com.google.gson.JsonParser;
import dev.hua.ptcglive.ai.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch101Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("sm12_en_202","sc_csm2bc_186_sr");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static ServerMatch aiGame(String id){return game(id,false);}
    static ServerMatch game(String id,boolean first){
        var kinds=List.of("base","base","base","base","gx","gx","normal","stage2","trainer","trainer","energy","energy","special","alias");
        var defs=new ArrayList<CardDefinition>();var profiles=new HashMap<String,PokemonProfile>();
        var attack=BundledCombatData.attack(JsonParser.parseString("{\"id\":\"hit\",\"nameZh\":\"hit\",\"energyCost\":{},\"baseDamage\":100,\"damageType\":\"COLORLESS\",\"effectSupport\":\"SUPPORTED\"}").getAsJsonObject(),EffectRegistry.standard());
        for(String key:new LinkedHashSet<>(kinds)){
            boolean pokemon=!Set.of("energy","special","trainer").contains(key),gx=Set.of("gx","stage2").contains(key);
            defs.add(new CardDefinition(key,key,pokemon?CardCategory.POKEMON:key.equals("trainer")?CardCategory.TRAINER:CardCategory.ENERGY,key.equals("trainer")?TrainerCategory.SUPPORTER:TrainerCategory.NONE,"H",Set.of("international"),Set.of("base","alias").contains(key),key.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null,gx?Set.of(PokemonFamily.GX):Set.of(),pokemon?Set.of(EnergyType.GRASS):Set.of()));
            if(pokemon)profiles.put(key,new PokemonProfile(300,0,Set.of("gx","normal").contains(key)?"base":key.equals("stage2")?"normal":null,null,0,null,0,gx?2:1,List.of(attack),List.of(),EnergyType.GRASS,key,null));
        }
        var combat=new CombatCatalog(profiles,Map.of("energy",EnergyType.GRASS),Map.of("trainer",NonPokemonBatch2Test.DATA.trainer(id).orElseThrow()),Map.of("special",EnergyProfile.fixed(EnergyType.GRASS,2)));
        for(int seed=0;seed<500;seed++){
            var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,kinds.get(i%kinds.size())));decks.add(cards);}
            var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("base")).count()<2))continue;
            OpeningTestSupport.complete(m,A,B,1);if(List.of(A,B).stream().anyMatch(p->!m.activePokemonView(p).topCardId().equals("base")||!m.benchPokemonView(p).getFirst().topCardId().equals("base")))continue;
            m.drawCardsByEffect(A,A,14);m.drawCardsByEffect(A,B,14);if(!first){m.endTurn(A);m.endTurn(B);}
            if(List.of(A,B).stream().allMatch(p->List.of("trainer","base","gx","normal","alias").stream().allMatch(k->m.privateView(p).hand().stream().anyMatch(c->c.definitionId().equals(k)))&&List.of("gx","normal","stage2","energy","special").stream().allMatch(k->m.privateView(p).deck().stream().anyMatch(c->c.definitionId().equals(k)))&&m.privateView(p).deck().stream().filter(c->c.definitionId().equals("energy")).count()>=2))return m;
        }throw new AssertionError("Red & Blue fixture unavailable");
    }
    static void select(ServerMatch m,UUID p,List<CardInstance> cards){var q=m.effectCardPrompt(p);m.submitEffectCards(p,q.resolutionId(),q.step(),cards.stream().map(CardInstance::instanceId).toList());}
    static void branch(ServerMatch m,UUID p,boolean extra){m.playTrainer(p,hand(m,p,"trainer").instanceId(),null);var q=m.effectChoicePrompt(p);m.chooseEffectOption(p,q.resolutionId(),q.step(),extra?1:0);}
    static List<CardInstance> pay(ServerMatch m,UUID p){var q=m.effectCardPrompt(p);check(q.minimum()==2&&q.maximum()==2&&q.candidates().stream().allMatch(m.privateView(p).hand()::contains),"Optional cost did not use two other original hand cards");var chosen=q.candidates().subList(0,2);select(m,p,chosen);return chosen;}
    static void host(ServerMatch m,UUID p,UUID host){var q=m.effectPokemonPrompt(p);m.chooseEffectPokemon(p,q.resolutionId(),q.step(),host);}
    static void evolve(ServerMatch m,UUID p){var q=m.effectCardPrompt(p);check(q.candidates().stream().allMatch(c->c.definitionId().equals("gx")),"Evolution search admitted non-GX/skipped stage/unrelated Pokemon");select(m,p,List.of(q.candidates().getFirst()));}
    public static void main(String[] args){resolutions();failedSearch();timing();payment();authority();ai();schema();System.out.println("NonPokemonBatch101Test passed: EN/CN Red-Blue, pre-evolution optional exact payment, direct GX/strict public timing and ancestry, actual evolved host binding, zero-one-two Basic Energy and failed searches, stale/foreign choices, all AI difficulties");}
    static void resolutions(){for(String id:IDS)for(UUID p:List.of(A,B))for(boolean bench:List.of(false,true))for(int count:List.of(-1,0,1,2)){
        var m=game(id,false);if(p.equals(B))m.endTurn(A);UUID target=bench?m.benchPokemonView(p).getFirst().pokemonId():active(m,p);var before=m.privateView(p).hand();branch(m,p,count>=0);List<CardInstance> costs=count<0?List.of():pay(m,p);check(EventTargetBindingTest.field(m).topCard(p,target).definitionId().equals("base"),"Evolved before extra payment");host(m,p,target);evolve(m,p);
        check(EventTargetBindingTest.field(m).topCard(p,target).definitionId().equals("gx"),"Did not evolve selected host");if(count>=0){var q=m.effectCardPrompt(p);check(q!=null&&q.minimum()==0&&q.maximum()==2&&q.candidates().stream().allMatch(c->c.definitionId().equals("energy")),"Extra attachment missing or admitted Special Energy");select(m,p,q.candidates().stream().limit(count).toList());}
        check(!m.hasPendingEffectChoice()&&m.currentPlayer().equals(p),"Red-Blue stalled or ended turn");check(EventTargetBindingTest.field(m).attachedEnergy(p,target).size()==Math.max(0,count),"Wrong energy count/host");check(m.privateView(p).discard().containsAll(costs)&&m.privateView(p).hand().size()==before.size()-1-costs.size(),"Wrong payment or searched energy went to hand");check((bench?m.activePokemonView(p):m.benchPokemonView(p).getFirst()).attachedEnergyIds().isEmpty(),"Attached to other Pokemon");
    }}
    static void failedSearch(){for(boolean noCard:List.of(false,true))for(boolean extra:List.of(false,true)){
        var m=game(IDS.getFirst(),false);if(noCard){var deck=PairedTrainerPlayTest.zone(m,A,"deck");var removed=deck.stream().filter(c->c.definitionId().equals("gx")).toList();deck.removeAll(removed);PairedTrainerPlayTest.zone(m,A,"discard").addAll(removed);}check(m.canPlayTrainer(A,hand(m,A,"trainer").instanceId(),null),"Hidden deck content made public play illegal");int rng=m.randomTranscript().size();branch(m,A,extra);if(extra)pay(m,A);host(m,A,active(m,A));if(m.hasPendingCardSelection())select(m,A,List.of());check(!m.hasPendingEffectChoice()&&m.activePokemonView(A).topCardId().equals("base")&&m.activePokemonView(A).attachedEnergyIds().isEmpty()&&m.randomTranscript().size()>rng,"Failed evolution still attached or did not shuffle");
    }}
    static void timing(){for(UUID p:List.of(A,B)){var m=game(IDS.getFirst(),true);if(p.equals(B))m.endTurn(A);check(!m.canPlayTrainer(p,hand(m,p,"trainer").instanceId(),null),"First own turn allowed");}
        for(String reason:List.of("fresh","evolved","unrelated","blocked")){var m=game(IDS.getFirst(),false);UUID target=active(m,A);if(reason.equals("fresh")){m.playBasicPokemonToBench(A,hand(m,A,"base").instanceId());target=m.benchPokemonView(A).getLast().pokemonId();}else if(reason.equals("evolved"))m.evolve(A,target,hand(m,A,"normal").instanceId());else if(reason.equals("unrelated")){m.playBasicPokemonToBench(A,hand(m,A,"alias").instanceId());m.endTurn(A);m.endTurn(B);target=m.benchPokemonView(A).getLast().pokemonId();}else m.preventEvolutionByEffect(A,A,target);
            branch(m,A,false);UUID excluded=target;check(m.effectPokemonPrompt(A).targets().stream().noneMatch(t->t.pokemonId().equals(excluded)),"Illegal host offered: "+reason);NonPokemonBatch2Test.settle(m);}
        var onlyGx=game(IDS.getFirst(),false);for(var p:new ArrayList<>(onlyGx.benchPokemonView(A)))onlyGx.movePokemonByEffect(A,A,p.pokemonId(),LeavePlayDestination.HAND);onlyGx.evolve(A,active(onlyGx,A),hand(onlyGx,A,"gx").instanceId());onlyGx.endTurn(A);onlyGx.endTurn(B);check(!onlyGx.canPlayTrainer(A,hand(onlyGx,A,"trainer").instanceId(),null),"Only un-evolvable GX in play can use Red-Blue");
    }
    static void payment(){for(int n:List.of(0,1,2)){var m=game(IDS.getFirst(),false);var source=hand(m,A,"trainer");var hand=PairedTrainerPlayTest.zone(m,A,"hand");var rest=hand.stream().filter(c->!c.equals(source)).toList();var removed=rest.subList(n,rest.size());hand.removeAll(removed);PairedTrainerPlayTest.zone(m,A,"discard").addAll(removed);m.playTrainer(A,source.instanceId(),null);check(m.canChooseEffectOption(A,1)==(n==2),"Extra branch ignored exact cost");if(n<2){var q=m.effectChoicePrompt(A);GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->m.chooseEffectOption(A,q.resolutionId(),q.step(),1));m.chooseEffectOption(A,q.resolutionId(),q.step(),0);}else{var q=m.effectChoicePrompt(A);m.chooseEffectOption(A,q.resolutionId(),q.step(),1);var c=m.effectCardPrompt(A);GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->select(m,A,List.of(source,c.candidates().getFirst())));GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->select(m,A,c.candidates().subList(0,1)));pay(m,A);}NonPokemonBatch2Test.settle(m);}}
    static void authority(){var m=game(IDS.getFirst(),false);branch(m,A,true);pay(m,A);var h=m.effectPokemonPrompt(A);GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->m.chooseEffectPokemon(B,h.resolutionId(),h.step(),active(m,A)));host(m,A,active(m,A));var q=m.effectCardPrompt(A);var bad=m.privateView(A).deck().stream().filter(c->c.definitionId().equals("normal")).findFirst().orElseThrow();GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->select(m,A,List.of(bad)));evolve(m,A);GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(q.candidates().getFirst().instanceId())));var energy=m.effectCardPrompt(A);GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->m.submitEffectCards(B,energy.resolutionId(),energy.step(),List.of(energy.candidates().getFirst().instanceId())));GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->select(m,A,List.of(energy.candidates().getFirst(),energy.candidates().getFirst())));select(m,A,energy.candidates().subList(0,2));}
    static void ai(){for(String id:IDS)for(var d:AiDifficulty.values()){var m=game(id,false);branch(m,A,true);AiCardOperationTest.settle(MatchSession.multiplayer(m,A,B),d);check(!m.hasPendingEffectChoice()&&m.phase()==MatchPhase.TURN,"AI stalled Red-Blue extra branch: "+id+" "+d);}}
    static void schema(){var e=new EffectDefinition("evolve_selected_from_deck",EffectTarget.SELECT_OWN_POKEMON,Map.of("target_count","1","minimum","1","evolution_timing","STRICT","evolution_family","GX","bind_pokemon","red-blue-evolved"),List.of(),List.of());TrainerDeckEvolution.validate(e);for(var kv:Map.of("target_count","2","minimum","0","evolution_timing","ANY","evolution_family","V","bind_pokemon","other").entrySet()){var a=new HashMap<>(e.arguments());a.put(kv.getKey(),kv.getValue());GeneratedRuleBatch8Test.reject(()->TrainerDeckEvolution.validate(new EffectDefinition(e.type(),e.target(),a,List.of(),List.of())));}}
}
